import{_ as e,o as t,c as a,a2 as r}from"./chunks/framework.vLhlLNVn.js";const m=JSON.parse('{"title":"🛡️ AI Agent 五大架构防线（强约束）","description":"","frontmatter":{},"headers":[],"relativePath":"standards/agent-rules.md","filePath":"standards/agent-rules.md"}'),d={name:"standards/agent-rules.md"};function l(i,o,s,c,n,g){return t(),a("div",null,[...o[0]||(o[0]=[r('<h1 id="🛡️-ai-agent-五大架构防线-强约束" tabindex="-1">🛡️ AI Agent 五大架构防线（强约束） <a class="header-anchor" href="#🛡️-ai-agent-五大架构防线-强约束" aria-label="Permalink to &quot;🛡️ AI Agent 五大架构防线（强约束）&quot;">​</a></h1><p>凡受命修改或编写 MzMedia 平台源码的 <strong>AI Agent（Coding Assistant）<strong>与核心研发人员，必须</strong>无条件执行</strong>以下五大防线约束：</p><hr><h2 id="防线一-业务逻辑独立模块化防线" tabindex="-1">防线一：业务逻辑独立模块化防线 <a class="header-anchor" href="#防线一-业务逻辑独立模块化防线" aria-label="Permalink to &quot;防线一：业务逻辑独立模块化防线&quot;">​</a></h2><ul><li><strong>视频业务</strong>（SIP、ZLMediaKit、WebRTC、PTZ）代码<strong>必须</strong>放在 <code>yudao-module-media</code> 中；</li><li><strong>物联网核心</strong>（协议网关、TSL 物模型、规则引擎）代码<strong>必须</strong>放在 <code>yudao-module-iot</code> 中；</li><li><strong>AI 智能体</strong>（Spring AI、MCP、Agent 编排）代码<strong>必须</strong>放在 <code>yudao-module-ai1-springai</code> 中；</li><li><strong>工业产供销业务</strong>必须分别落在 <code>pms</code>、<code>mes</code>、<code>wms</code> 中；</li><li><strong>严禁侵入核心底座</strong>：<strong>绝对禁止</strong>直接修改 <code>yudao-framework</code> 或 <code>yudao-module-system</code> 的内部核心逻辑！若需要扩展框架能力，必须使用 <strong>Spring 继承拓展</strong>、<strong><code>@Primary</code> Bean 覆盖</strong> 或 <strong>AOP 切面注入</strong> 实现。</li></ul><hr><h2 id="防线二-配置文件隔离防线" tabindex="-1">防线二：配置文件隔离防线 <a class="header-anchor" href="#防线二-配置文件隔离防线" aria-label="Permalink to &quot;防线二：配置文件隔离防线&quot;">​</a></h2><ul><li>禁止在根配置 <code>application.yaml</code> 中大规模修改官方现有参数；</li><li>新增业务配置必须挂载在专属命名空间下： <ul><li>视频模块：<code>sip:</code>、<code>media:</code>、<code>user-settings:</code></li><li>物联网模块：<code>yudao.iot:</code></li><li>AI 模块：<code>yudao.ai:</code>、<code>spring.ai:</code></li></ul></li><li><strong>安全底线</strong>：严禁将任何真实的生产数据库密码、第三方 API Key、云存储密钥硬编码提交到 Git 仓库，统一使用环境变量占位符（如 <code>${OPENAI_API_KEY:sk-xxxx}</code>）。</li></ul><hr><h2 id="防线三-数据库脚本增量管理防线" tabindex="-1">防线三：数据库脚本增量管理防线 <a class="header-anchor" href="#防线三-数据库脚本增量管理防线" aria-label="Permalink to &quot;防线三：数据库脚本增量管理防线&quot;">​</a></h2><ul><li><strong>绝对禁止修改官方基线脚本</strong>：严禁直接篡改 <code>sql/mysql/ruoyi-vue-pro.sql</code>；</li><li><strong>增量脚本规范</strong>：所有新增业务表、新增字段、新增菜单与字典，必须以独立文件形式存储在 <code>sql/module/</code> 下，命名规则为 <code>模块名-yyyy-MM-dd.sql</code>（例如 <code>sql/module/media-2026-11-10.sql</code>）。</li></ul><hr><h2 id="防线四-代码设计与分层规范防线" tabindex="-1">防线四：代码设计与分层规范防线 <a class="header-anchor" href="#防线四-代码设计与分层规范防线" aria-label="Permalink to &quot;防线四：代码设计与分层规范防线&quot;">​</a></h2><ul><li><strong>三层架构分层</strong>： <ul><li><code>Controller</code>：只负责入参校验（<code>@Valid</code>）、权限控制（<code>@PreAuthorize</code>）与结果组装，<strong>禁止在 Controller 中书写核心业务逻辑</strong>；</li><li><code>Service</code> / <code>ServiceImpl</code>：承载所有核心业务事务与流程控制；</li><li><code>DAL</code>（Data Access Layer）：分为 <code>dataobject</code>（DO 实体）与 <code>mysql</code>（Mapper 接口），使用 MyBatis-Plus。</li></ul></li><li><strong>数据转换统一标准</strong>： <ul><li>强制使用 <strong>MapStruct</strong> 编写转换器接口（如 <code>DeviceConvert.INSTANCE.convert(do)</code>），<strong>严禁在代码中写手工重复的 <code>get/set</code></strong>，也不建议使用性能损耗严重的 <code>BeanUtils.copyProperties</code>。</li></ul></li><li><strong>接口返回结构统一</strong>： <ul><li>所有 API 返回类型必须为 <code>CommonResult&lt;T&gt;</code>，成功使用 <code>CommonResult.success(data)</code>，失败使用 <code>ServiceException</code> 抛出，由全局异常拦截器统一收敛。</li></ul></li><li><strong>多租户与数据隔离</strong>： <ul><li>属于租户层级的业务表必须包含 <code>tenant_id</code> 字段（<code>bigint NOT NULL DEFAULT 0</code>）。</li></ul></li></ul><hr><h2 id="防线五-java-21-与编译环境防线" tabindex="-1">防线五：Java 21 与编译环境防线 <a class="header-anchor" href="#防线五-java-21-与编译环境防线" aria-label="Permalink to &quot;防线五：Java 21 与编译环境防线&quot;">​</a></h2><ul><li>项目已全面升级至 <strong>Java 21</strong> 与 <strong>Spring Boot 4.1.2</strong>，严禁引入已过时的 Javax 包（必须使用 <code>jakarta.*</code>，如 <code>jakarta.annotation.Resource</code>、<code>jakarta.validation.Valid</code>）；</li><li>根目录 <code>pom.xml</code> 中必须保留 <code>&lt;compilerArgs&gt;&lt;arg&gt;-parameters&lt;/arg&gt;&lt;/compilerArgs&gt;</code>，以确保 Spring Boot 参数名反射推导正常运作。</li></ul>',17)])])}const h=e(d,[["render",l]]);export{m as __pageData,h as default};
